"""Local playback index; timing flags remain unresolved and unchanged."""
from pathlib import Path
import json,html,math,hashlib,sys
root=Path(__file__).resolve().parents[4];out=(root/'outputs'/(sys.argv[1] if len(sys.argv)>1 else 'evan-cartoon-continuous')).resolve()
if out.parent!=root/'outputs' or not out.is_dir():raise ValueError('Expected an existing review folder directly inside outputs')
p=root/'work/engine/evan-engine/reviews/evan-reference-timing-v1.json';review=json.loads(p.read_text());words=review['words'];assert len(words)==18
rows=[];markers=[]
for w in words:
 a,b=w['acoustic'];c,d=w['anchor'];assert b>a>=0 and d>c>=0
 region=root/'outputs/evan-speech-exact-review-audio'/w['region'];assert region.is_file() and region.with_suffix('.wav').is_file()
 markers.append(dict(scriptIndex=w['scriptIndex'],word=w['word'],acoustic=[a,b],anchor=[c,d],frameWindow24=[math.floor(a*24),math.ceil(b*24)],boundaryStatus=w['boundaryStatus'],region=w['region']))
 rows.append(f'<tr><td>{html.escape(w["word"])}</td><td><button data-time="{a}">{a:.2f}–{b:.2f}s</button></td><td><button data-time="{c}">{c:.2f}–{d:.2f}s</button></td><td><a href="../evan-speech-exact-review-audio/{w["region"]}">Waveform / spectrogram</a> · <a href="../evan-speech-exact-review-audio/{region.with_suffix(".wav").name}">Exact context audio</a></td></tr>')
(out/'Timing-Markers.json').write_text(json.dumps(dict(sourceReviewSha256=hashlib.sha256(p.read_bytes()).hexdigest(),flagsCleared=0,markers=markers),indent=2)+'\n')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><title>Evan continuous cartoon review</title><style>body{max-width:1280px;margin:32px auto;padding:0 20px;background:#f3eee2;color:#233442;font:17px/1.5 system-ui}video{width:100%;background:#d9e3dc}table{border-collapse:collapse;width:100%}td,th{padding:8px;text-align:left;border-bottom:1px solid #bdc8c6}button{font:inherit;cursor:pointer}a{color:#245d77}details{margin:20px 0}</style><h1>Evan continuous cartoon review</h1><p>Current separated speech face and narration-driven staging, followed by the guarded raised-hand ending. This is a working construction review; expressive acting, independent listening and exact phoneme boundaries remain unapproved.</p><p>Chapters: <button data-time="0">Opening</button> <button data-time="5.36">Browser explanation</button> <button data-time="10.19">Favicon definition</button> <button data-time="14.72">Small detail / payoff</button> <button data-time="19.52">Rovor closing line</button> <button data-time="22.1666667">Guarded ending</button></p><h2>Normal speed · original narration</h2><video id="normal" controls preload="metadata" src="Normal.mp4"></video><details><summary>Muted quarter speed</summary><video id="slow" controls muted preload="metadata" src="Quarter-Speed.mp4"></video></details><p>Select a time below to cue both films. Times are from the original recording; the slow film uses four times that position. Playback is24fps, so it cannot establish very short consonant boundaries. No alignment was retimed.</p><h2>18 retained timing flags</h2><p>Acoustic intervals and older word anchors are comparison cues. All exact boundaries remain unverified. Links retain the existing waveform/spectrogram findings and byte-exact source context.</p><table><thead><tr><th>Word</th><th>Acoustic interval</th><th>Older anchor</th><th>Evidence</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table><p><a href="../evan-speech-exact-review-audio/Timing-Review.html">Original six-region timing review</a> · <a href="Verification.json">Render verification</a> · <a href="Review-Evidence.json">Current review limits</a></p><script>document.addEventListener('click',e=>{const b=e.target.closest('button[data-time]');if(!b)return;const t=Number(b.dataset.time);if(!Number.isFinite(t)||t<0)return;for(const [id,scale]of[['normal',1],['slow',4]]){const v=document.getElementById(id);v.pause();v.currentTime=Math.min(t*scale,Number.isFinite(v.duration)?v.duration:t*scale);}});</script></html>'''
assert page.count('<tr><td>')==18 and all(w['boundaryStatus']=='exact-boundaries-unverified' for w in words)
page=page.replace('<h1>Evan continuous cartoon review</h1>', '<h1>Evan continuous cartoon review</h1><p>'+('Full films have passed export checks; performance approval remains pending.' if (out/'Verification.json').exists() else 'Full film is still rendering. Playback files will appear after export verification.')+'</p>')
(out/'Review.html').write_text(page);print('18 unresolved timing markers and evidence links saved')
